    "gateway":  { "cx": 14, "cy": 11, "w": 4, "h": 3, "borderColor": "blue", "icon": "onprem/network/traefik", "iconPosition": "top" },
    "web":      { "cx": 20, "cy": 4,  "w": 4, "h": 2, "borderColor": "purple", "icon": "programming/framework/react" },
    "api":      { "cx": 20, "cy": 11, "w": 4, "h": 2, "borderColor": "purple", "icon": "programming/framework/fastapi" },
    "auth":     { "cx": 20, "cy": 18, "w": 4, "h": 2, "borderColor": "purple", "icon": "aws/security/cognito" },
    "bucket":   { "cx": 27, "cy": 3,  "w": 4, "h": 2, "borderColor": "teal", "icon": "aws/storage/simple-storage-service-s3" },
    "postgres": { "cx": 27, "cy": 7,  "w": 4, "h": 2, "borderColor": "teal", "icon": "onprem/database/postgresql" },
    "redis":    { "cx": 27, "cy": 11, "w": 4, "h": 2, "borderColor": "teal", "icon": "onprem/inmemory/redis" },
    "events":   { "cx": 27, "cy": 15, "w": 4, "h": 2, "borderColor": "teal", "icon": "onprem/queue/kafka" },
    "workers":  { "cx": 27, "cy": 19, "w": 4, "h": 2, "borderColor": "teal", "icon": "aws/compute/lambda" },
